using System.Security.Claims;
using FindUpTo.Pos.Server.Data;
using FindUpTo.Pos.Server.Hubs;
using FindUpTo.Pos.Server.Models;
using FindUpTo.Pos.Server.Services;
using Microsoft.AspNetCore.SignalR;
using Microsoft.EntityFrameworkCore;

namespace FindUpTo.Pos.Server.Endpoints;

public static class WorkflowEndpoints
{
    private static readonly string[] PaymentMethods = ["Cash", "Card", "Online"];
    private static readonly string[] OrderTypes = ["Counter", "Dine In", "Pickup", "Delivery"];

    public static void MapWorkflowEndpoints(this WebApplication app)
    {
        PaymentReconciliationEndpoints.MapPaymentReconciliationEndpoints(app);
        app.MapPost("/api/orders", async (CreateOrderRequest input, ClaimsPrincipal user, CoreDbContext db, IHubContext<PosHub> hub, PromotionPricingService pricing, InventoryService inventory) =>
        {
            if (input.Items is null || input.Items.Count == 0) return Results.BadRequest("Order must contain at least one item."); if (input.Items.Count > 100) return Results.BadRequest("An order cannot contain more than 100 line items.");
            var orderTypeInput = input.OrderType?.Trim() ?? ""; if (!OrderTypes.Contains(orderTypeInput, StringComparer.OrdinalIgnoreCase)) return Results.BadRequest("Invalid order type.");
            if (input.ClientOperationId?.Trim().Length > 128) return Results.BadRequest("ClientOperationId is too long."); var operationId = input.ClientOperationId?.Trim() ?? "";
            if (operationId.Length > 0) { var duplicate = await db.SyncOperations.AsNoTracking().SingleOrDefaultAsync(x => x.ClientOperationId == operationId); if (duplicate is not null) return Results.Ok(await db.Orders.AsNoTracking().Include(x => x.Items).SingleAsync(x => x.Id == duplicate.OrderId)); }
            if (input.CustomerId.HasValue && !await db.Customers.AnyAsync(x => x.Id == input.CustomerId.Value)) return Results.BadRequest("Customer not found."); if (input.TableId.HasValue && !await db.Tables.AnyAsync(x => x.Id == input.TableId.Value && x.Active)) return Results.BadRequest("Table not found or inactive."); if (orderTypeInput.Equals("Dine In", StringComparison.OrdinalIgnoreCase) && !input.TableId.HasValue) return Results.BadRequest("A table is required for Dine In orders."); if (orderTypeInput.Equals("Delivery", StringComparison.OrdinalIgnoreCase) && !input.CustomerId.HasValue) return Results.BadRequest("A customer is required for Delivery orders.");
            var ids = input.Items.Select(x => x.ProductId).Distinct().ToList(); var products = await db.Products.AsNoTracking().Where(x => ids.Contains(x.Id) && x.Available).ToDictionaryAsync(x => x.Id); if (products.Count != ids.Count) return Results.BadRequest("One or more products are unavailable.");
            var inventoryCosts = await db.ProductInventories.AsNoTracking().Where(x => ids.Contains(x.ProductId)).ToDictionaryAsync(x => x.ProductId, x => x.AverageCost);
            var order = new PosOrder { CustomerId = input.CustomerId, TableId = input.TableId, CreatedByUsername = user.Identity?.Name ?? "unknown", OrderType = OrderTypes.First(x => x.Equals(orderTypeInput, StringComparison.OrdinalIgnoreCase)), Notes = input.Notes?.Trim() ?? "" };
            foreach (var item in input.Items) { if (item.Quantity <= 0 || item.Quantity > 10000) return Results.BadRequest("Quantity must be between 1 and 10000."); var product = products[item.ProductId]; order.Items.Add(new OrderItem { ProductId = product.Id, ProductName = product.Name, UnitPrice = Math.Round(product.Price, 2), UnitCost = inventoryCosts.GetValueOrDefault(product.Id), Quantity = item.Quantity, Notes = item.Notes?.Trim() ?? "", LineTotal = Math.Round(product.Price * item.Quantity, 2) }); }
            await pricing.ApplyAsync(order, products);
            await using var tx = db.Database.IsRelational() ? await db.Database.BeginTransactionAsync() : null;
            db.Orders.Add(order); await db.SaveChangesAsync(); var inventoryResult = await inventory.DeductForSaleAsync(order); if (!inventoryResult.Success) { if (tx is not null) await tx.RollbackAsync(); return Results.Conflict(new { message = "Insufficient stock.", productId = inventoryResult.ProductId, productName = inventoryResult.ProductName, required = inventoryResult.Required, available = inventoryResult.Available }); }
            if (order.OrderType.Equals("Delivery", StringComparison.OrdinalIgnoreCase) && !await db.DeliveryTrackings.AnyAsync(x => x.OrderId == order.Id)) { db.DeliveryTrackings.Add(new DeliveryTracking { OrderId = order.Id, TrackingCode = await CreateTrackingCodeAsync(db), Status = "Preparing" }); await db.SaveChangesAsync(); }
            if (operationId.Length > 0) { db.SyncOperations.Add(new SyncOperation { ClientOperationId = operationId, OrderId = order.Id, CreatedByUsername = user.Identity?.Name ?? "unknown" }); try { await db.SaveChangesAsync(); } catch (DbUpdateException) { if (tx is not null) await tx.RollbackAsync(); var raced = await db.SyncOperations.AsNoTracking().SingleOrDefaultAsync(x => x.ClientOperationId == operationId); if (raced is not null) return Results.Ok(await db.Orders.AsNoTracking().Include(x => x.Items).SingleAsync(x => x.Id == raced.OrderId)); throw; } }
            if (tx is not null) await tx.CommitAsync(); await AuditEndpoints.WriteAsync(db, user, "Created", "Order", order.Id.ToString(), operationId.Length == 0 ? "" : $"ClientOperationId={operationId}"); await hub.Clients.All.SendAsync("order.updated", new { orderId = order.Id, status = order.Status, total = order.Total, updatedAtUtc = order.UpdatedAtUtc }); return Results.Created($"/api/orders/{order.Id}", order);
        }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Counter", "Waiter"));

        app.MapGet("/api/orders", async (CoreDbContext db, string? status) => { var q = db.Orders.AsNoTracking().Include(x => x.Items).AsQueryable(); if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status.Trim()); return Results.Ok(await q.OrderByDescending(x => x.CreatedAtUtc).Take(500).ToListAsync()); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Counter", "Waiter", "Kitchen", "Rider"));
        app.MapPatch("/api/orders/{id:int}/status", async (int id, UpdateOrderStatusRequest input, ClaimsPrincipal user, CoreDbContext db, IHubContext<PosHub> hub, InventoryService inventory) => { var allowed = new[] { "New", "Accepted", "Preparing", "Ready", "Served", "OutForDelivery", "Completed", "Cancelled" }; if (!allowed.Contains(input.Status, StringComparer.OrdinalIgnoreCase)) return Results.BadRequest("Invalid order status."); var order = await db.Orders.FindAsync(id); if (order is null) return Results.NotFound(); var next = allowed.First(x => x.Equals(input.Status, StringComparison.OrdinalIgnoreCase)); if (next == "Completed" && order.OrderType.Equals("Delivery", StringComparison.OrdinalIgnoreCase) && !order.Status.Equals("OutForDelivery", StringComparison.OrdinalIgnoreCase)) return Results.BadRequest("Delivery orders must be out for delivery before completion."); if (next == "OutForDelivery" && (!order.OrderType.Equals("Delivery", StringComparison.OrdinalIgnoreCase) || !order.Status.Equals("Ready", StringComparison.OrdinalIgnoreCase))) return Results.BadRequest("Only ready delivery orders can go out for delivery."); if (next == "Cancelled" && order.Status.Equals("Cancelled", StringComparison.OrdinalIgnoreCase)) return Results.BadRequest("Order is already cancelled."); await using var tx = next == "Cancelled" && db.Database.IsRelational() ? await db.Database.BeginTransactionAsync() : null; IReadOnlyList<int> restoredProducts = []; if (next == "Cancelled") restoredProducts = await inventory.RestoreForCancellationAsync(order, user.Identity?.Name ?? "unknown"); order.Status = next; order.UpdatedAtUtc = DateTime.UtcNow; await db.SaveChangesAsync(); if (tx is not null) await tx.CommitAsync(); await AuditEndpoints.WriteAsync(db, user, "StatusChanged", "Order", order.Id.ToString(), $"Status={order.Status}"); await hub.Clients.All.SendAsync("order.updated", new { orderId = order.Id, status = order.Status, total = order.Total, updatedAtUtc = order.UpdatedAtUtc }); foreach (var productId in restoredProducts) { var stock = await db.ProductInventories.AsNoTracking().SingleAsync(x => x.ProductId == productId); await hub.Clients.All.SendAsync("inventory.updated", new { productId, quantityOnHand = stock.QuantityOnHand, reorderLevel = stock.ReorderLevel, averageCost = stock.AverageCost, trackInventory = stock.TrackInventory, updatedAtUtc = stock.UpdatedAtUtc }); } return Results.Ok(order); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Counter", "Waiter", "Kitchen", "Rider"));
        app.MapPost("/api/orders/{id:int}/payment", async (int id, CollectPaymentRequest input, ClaimsPrincipal user, CoreDbContext db) => { if (input.AmountTendered <= 0) return Results.BadRequest("Amount tendered must be greater than zero."); var method = input.Method?.Trim() ?? ""; if (!PaymentMethods.Contains(method, StringComparer.OrdinalIgnoreCase)) return Results.BadRequest("Payment method must be Cash, Card, or Online."); var order = await db.Orders.SingleOrDefaultAsync(x => x.Id == id); if (order is null) return Results.NotFound(); if (order.Status.Equals("Cancelled", StringComparison.OrdinalIgnoreCase)) return Results.BadRequest("Cancelled orders cannot be paid."); var clientOperationId = input.ClientOperationId?.Trim() ?? ""; if (clientOperationId.Length > 128) return Results.BadRequest("ClientOperationId is too long."); if (clientOperationId.Length > 0) { var previous = await db.Payments.AsNoTracking().SingleOrDefaultAsync(x => x.ClientOperationId == clientOperationId); if (previous is not null) return Results.Ok(previous); } var alreadyCollected = Math.Round(await db.Payments.Where(x => x.PosOrderId == id && x.Status.Equals("Paid", StringComparison.OrdinalIgnoreCase)).SumAsync(x => x.AmountPaid - x.ChangeAmount), 2); var outstanding = Math.Round(order.Total - alreadyCollected, 2); if (outstanding <= 0) return Results.Conflict("Order is already paid."); var tendered = Math.Round(input.AmountTendered, 2); var isCash = method.Equals("Cash", StringComparison.OrdinalIgnoreCase); var applied = Math.Min(tendered, outstanding); var change = isCash ? Math.Round(tendered - applied, 2) : 0m; if (!isCash && tendered > outstanding) return Results.BadRequest("Card and Online payments cannot exceed the outstanding balance."); if (!isCash && string.IsNullOrWhiteSpace(input.Reference)) return Results.BadRequest("A payment reference is required for Card and Online payments."); var payment = new Payment { PosOrderId = id, AmountTendered = tendered, AmountPaid = Math.Round(applied, 2), ChangeAmount = change, Method = PaymentMethods.First(x => x.Equals(method, StringComparison.OrdinalIgnoreCase)), Reference = input.Reference?.Trim() ?? "", ClientOperationId = clientOperationId, CollectedByUsername = user.Identity?.Name ?? "unknown" }; db.Payments.Add(payment); try { await db.SaveChangesAsync(); } catch (DbUpdateException) when (clientOperationId.Length > 0) { var previous = await db.Payments.AsNoTracking().SingleOrDefaultAsync(x => x.ClientOperationId == clientOperationId); if (previous is not null) return Results.Ok(previous); throw; } await AuditEndpoints.WriteAsync(db, user, "Paid", "Payment", payment.Id.ToString(), $"OrderId={id};Method={payment.Method};Amount={payment.AmountPaid:0.00}"); var hub = app.Services.GetRequiredService<IHubContext<PosHub>>(); await hub.Clients.All.SendAsync("payment.updated", new { orderId = id, paymentId = payment.Id, status = payment.Status, method = payment.Method, amountPaid = payment.AmountPaid, changeAmount = payment.ChangeAmount, outstandingAmount = Math.Round(outstanding - payment.AmountPaid, 2) }); return Results.Ok(payment); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Counter"));
        app.MapGet("/api/orders/{id:int}/payments", async (int id, CoreDbContext db) => { if (!await db.Orders.AnyAsync(x => x.Id == id)) return Results.NotFound(); return Results.Ok(await db.Payments.AsNoTracking().Where(x => x.PosOrderId == id).OrderByDescending(x => x.CreatedAtUtc).ToListAsync()); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Counter"));
        app.MapGet("/api/kitchen/orders", async (CoreDbContext db, string? status) => { var allowed = new[] { "New", "Accepted", "Preparing", "Ready" }; var q = db.Orders.AsNoTracking().Include(x => x.Items).Where(x => allowed.Contains(x.Status)); if (!string.IsNullOrWhiteSpace(status)) q = q.Where(x => x.Status == status.Trim()); return Results.Ok(await q.OrderBy(x => x.CreatedAtUtc).Take(200).ToListAsync()); }).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Kitchen"));
        app.MapGet("/api/waiter/orders", async (CoreDbContext db) => Results.Ok(await db.Orders.AsNoTracking().Include(x => x.Items).Where(x => x.OrderType == "Dine In" && x.Status != "Completed" && x.Status != "Cancelled").OrderByDescending(x => x.CreatedAtUtc).Take(200).ToListAsync())).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Waiter"));
        app.MapGet("/api/rider/orders", async (CoreDbContext db) => Results.Ok(await db.Orders.AsNoTracking().Include(x => x.Items).Where(x => x.OrderType == "Delivery" && x.Status == "OutForDelivery").OrderBy(x => x.CreatedAtUtc).Take(200).ToListAsync())).RequireAuthorization(p => p.RequireRole("Owner", "Manager", "Admin", "Rider"));
    }

    private static async Task<string> CreateTrackingCodeAsync(CoreDbContext db)
    {
        for (var attempt = 0; attempt < 5; attempt++)
        {
            var code = $"FU{Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(6))}";
            if (!await db.DeliveryTrackings.AnyAsync(x => x.TrackingCode == code)) return code;
        }
        throw new InvalidOperationException("Unable to allocate a unique delivery tracking code.");
    }
}

